public static String parseCpuArch(String hardwareSpec) {
    if (StringUtils.isBlank(hardwareSpec)) {
        return ARCH_UNKNOWN;
    }
    String lower = hardwareSpec.toLowerCase();
    for (Map.Entry<String, String> e : ARCH_KEYWORDS.entrySet()) {
        if (lower.contains(e.getKey())) {
            return e.getValue();
        }
    }
    return ARCH_UNKNOWN;
}

// 核对：产品侧架构与服务器架构不一致时才换替代型号
private boolean archMismatch(String productArch, String serverArch) {
    if (ARCH_UNKNOWN.equals(productArch) || ARCH_UNKNOWN.equals(serverArch)) {
        return false;                    // 解析不出来就不拦，避免误伤
    }
    return !productArch.equals(serverArch);
}

private void notifyDiscontinued(String productModel, List<Material> abnormal) {
    for (Material m : abnormal) {
        if (!m.isDiscontinued()) {
            continue;
        }
        // Caffeine：同一产品型号 + 物料号，24 小时内只发一次
        String key = productModel + "|" + m.getMaterialNo();
        if (notifyCache.getIfPresent(key) != null) {
            continue;
        }
        notifyCache.put(key, Boolean.TRUE);
        List<String> receivers = queryOwnerByRole(productModel, ROLE_PRODUCT_OWNER);
        if (CollectionUtils.isEmpty(receivers)) {
            // 角色白名单查不到就降级成该产品全部成员，宁滥勿缺
            receivers = queryAllMembers(productModel);
        }
        if (CollectionUtils.isEmpty(receivers)) {
            log.warn("no receiver for discontinued material, model: {}, material: {}",
                    productModel, m.getMaterialNo());
            continue;
        }
        imService.send(buildText(productModel, m), receivers);
    }
}
